  const handleUploadBankQrFormImage = async (
    e: React.ChangeEvent<HTMLInputElement>
  ) => {
    if (!requireAdminAuth('ອັບໂຫຼດຮູບ QR Code', 'upload Bank QR images')) return;
    const file = e.target.files?.[0];
    if (!file) return;
    try {
      const compressedDataUrl = await compressUploadedImage(file);
      setBankQrForm((prev) => ({
        ...prev,
        qrImageUrl: compressedDataUrl,
      }));
      showNotice(
        `ອັບໂຫຼດຮູບພາບ QR Code ທະນາຄານສຳເລັດ!`,
        `Uploaded custom Bank QR Code image!`
      );
    } catch {
      showNotice(
        'ບໍ່ສາມາດອ່ານໄຟລ໌ຮູບພາບ QR Code ໄດ້',
        'Could not read the QR Code image file.'
      );
    }
    e.target.value = '';
  };

  const handleDirectBankQrImageUpload = async (
    bankMethod: CompanyBankQrMethod,
    e: React.ChangeEvent<HTMLInputElement>
  ) => {
    if (!requireAdminAuth('ອັບໂຫຼດຮູບ QR Code', 'upload Bank QR images')) return;
    const file = e.target.files?.[0];
    if (!file) return;
    try {
      const compressedDataUrl = await compressUploadedImage(file);
      setBankQrMethods((prev) =>
        prev.map((b) =>
          b.id === bankMethod.id
            ? { ...b, qrImageUrl: compressedDataUrl }
            : b
        )
      );
      showNotice(
        `ອັບເດດຮູບ QR Code ສຳລັບ "${bankMethod.bankName}" ສຳເລັດ!`,
        `Updated QR Code image for "${bankMethod.bankName}"!`
      );
    } catch {
      showNotice(
        'ບໍ່ສາມາດອັບໂຫຼດຮູບ QR Code ໄດ້',
        'Could not upload QR Code image.'
      );
    }
    e.target.value = '';
  };

  const handleSaveBankQr = (e: React.FormEvent) => {
    e.preventDefault();
    if (!requireAdminAuth('ບັນທຶກທະນາຄານ & QR Code', 'save Bank QR methods')) return;
    const cleanBankName =
      sanitizeString(bankQrForm.bankName, 80) || 'BCEL One QR';
    const cleanAccName =
      sanitizeString(bankQrForm.accountName, 120) ||
      'PL Skincare Brand Co., Ltd.';
    const cleanAccNumber =
      sanitizeString(bankQrForm.accountNumber, 60) || '160-12-00-889900-001';
    const cleanQrPayload =
      sanitizeString(bankQrForm.qrPayload, 260) ||
      `LAOQR|${cleanBankName.toUpperCase().replace(/\s+/g, '_')}|${cleanAccNumber}|${cleanAccName}`;

    const record: CompanyBankQrMethod = {
      id: editingBankQr ? editingBankQr.id : `bank_qr_${Date.now()}`,
      bankName: cleanBankName,
      accountName: cleanAccName,
      accountNumber: cleanAccNumber,
      currency: bankQrForm.currency,
      qrPayload: cleanQrPayload,
      qrImageUrl: bankQrForm.qrImageUrl || '',
      status: bankQrForm.status,
    };

    setBankQrMethods((prev) => {
      const exists = prev.some((b) => b.id === record.id);
      if (exists) {
        return prev.map((b) => (b.id === record.id ? record : b));
      }
      return [...prev, record];
    });
    setSelectedBankForQrPayment(record.bankName);
    setShowBankQrForm(false);
    setEditingBankQr(null);
    showNotice(
      editingBankQr
        ? `ອັບເດດຊ່ອງທາງຊຳລະເງິນ & QR Code "${record.bankName}" ສຳເລັດ!`
        : `ເພີ່ມຊ່ອງທາງຊຳລະເງິນທະນາຄານ & QR Code "${record.bankName}" ສຳເລັດ!`,
      editingBankQr
        ? `Updated Bank Payment & QR Code "${record.bankName}"!`
        : `Added new Bank Payment & QR Code "${record.bankName}"!`
    );
  };

