  // ============================================================================
  // ADMINISTRATOR SHIPPING LOGISTICS CRUD (ANOUSITH LOGISTICS & HAL LOGISTICS)
  // ============================================================================
  const handleOpenCreateShipping = (presetCarrier?: string) => {
    if (!requireAdminAuth('ເພີ່ມບໍລິສັດຂົນສົ່ງ', 'add shipping carriers')) return;
    setEditingShipping(null);
    const isHal = presetCarrier?.toLowerCase().includes('hal');
    const nameEn = presetCarrier || 'Anousith Logistics';
    const nameLo = isHal
      ? 'ຮຸ່ງອາລຸນ ຂົນສົ່ງດ່ວນ (HAL Logistics)'
      : presetCarrier && !presetCarrier.toLowerCase().includes('anousith')
      ? `${presetCarrier} (ຂົນສົ່ງດ່ວນ)`
      : 'ອານຸສິດ ຂົນສົ່ງດ່ວນ (Anousith Express)';
    const code = isHal ? 'HAL' : 'ANS';
    setShippingForm({
      nameEn,
      nameLo,
      code,
      hotline: isHal ? '1418 / 020 9999 7788' : '1419 / 020 5555 8899',
      branchesText:
        'ສາຂາ ນະຄອນຫຼວງວຽງຈັນ (Vientiane Capital Main Hub), ສາຂາ ຈັນທະບູລີ (Chanthabouly Branch), ສາຂາ ໄຊເສດຖາ (Xaysettha Branch), ສາຂາ ຫຼວງພະບາງ (Luang Prabang Branch), ສາຂາ ສະຫວັນນະເຂດ (Savannakhet Branch), ສາຂາ ປາກເຊ - ຈຳປາສັກ (Pakse Champasak Branch)',
      deliveryFeeThb: 0,
      estimatedDaysLo: 'ຈັດສົ່ງດ່ວນ 1–2 ມື້ທົ່ວປະເທດ',
      estimatedDaysEn: '1–2 Days Express Nationwide',
      status: 'active',
    });
    setShowShippingForm(true);
  };

  const handleOpenEditShipping = (shipMethod: ShippingLogisticsMethod) => {
    if (!requireAdminAuth('ແກ້ໄຂບໍລິສັດຂົນສົ່ງ', 'edit shipping carriers')) return;
    setEditingShipping(shipMethod);
    setShippingForm({
      nameEn: shipMethod.nameEn,
      nameLo: shipMethod.nameLo,
      code: shipMethod.code,
      hotline: shipMethod.hotline,
      branchesText: shipMethod.defaultBranches.join(', '),
      deliveryFeeThb: shipMethod.deliveryFeeThb,
      estimatedDaysLo: shipMethod.estimatedDaysLo,
      estimatedDaysEn: shipMethod.estimatedDaysEn,
      status: shipMethod.status,
    });
    setShowShippingForm(true);
  };

  const handleSaveShipping = (e: React.FormEvent) => {
    e.preventDefault();
    if (!requireAdminAuth('ບັນທຶກບໍລິສັດຂົນສົ່ງ', 'save shipping carriers')) return;
    const cleanNameEn =
      sanitizeString(shippingForm.nameEn, 80) || 'Anousith Logistics';
    const cleanNameLo =
      sanitizeString(shippingForm.nameLo, 100) ||
      `${cleanNameEn} (ຂົນສົ່ງດ່ວນ)`;
    const cleanCode =
      sanitizeCode(shippingForm.code, 10) ||
      cleanNameEn.slice(0, 3).toUpperCase();
    const cleanHotline =
      sanitizeString(shippingForm.hotline, 60) || '1419 / 020 5555 8899';
    const parsedBranches = shippingForm.branchesText
      .split(',')
      .map((b) => b.trim())
      .filter(Boolean);
    const defaultBranches =
      parsedBranches.length > 0
        ? parsedBranches
        : ['ສາຂາ ນະຄອນຫຼວງວຽງຈັນ (Vientiane Capital Main Hub)'];

    const record: ShippingLogisticsMethod = {
      id: editingShipping ? editingShipping.id : `ship_${Date.now()}`,
      nameEn: cleanNameEn,
      nameLo: cleanNameLo,
      code: cleanCode,
      hotline: cleanHotline,
      defaultBranches,
      deliveryFeeThb: Math.max(0, Number(shippingForm.deliveryFeeThb) || 0),
      estimatedDaysLo:
        sanitizeString(shippingForm.estimatedDaysLo, 60) ||
        'ຈັດສົ່ງດ່ວນ 1–2 ມື້ທົ່ວປະເທດ',
      estimatedDaysEn:
        sanitizeString(shippingForm.estimatedDaysEn, 60) ||
        '1–2 Days Express Nationwide',
      status: shippingForm.status,
    };

    setShippingMethods((prev) => {
      const exists = prev.some((s) => s.id === record.id);
      if (exists) {
        return prev.map((s) => (s.id === record.id ? record : s));
      }
      return [...prev, record];
    });
    setSelectedShippingProvider(record.nameEn);
    if (record.defaultBranches.length > 0) {
      setShippingBranch(record.defaultBranches[0]);
    }
    setShowShippingForm(false);
    setEditingShipping(null);
    showNotice(
      editingShipping
        ? `ອັບເດດບໍລິສັດຂົນສົ່ງ "${record.nameEn}" ສຳເລັດ!`
        : `ເພີ່ມບໍລິສັດຂົນສົ່ງໃໝ່ "${record.nameEn}" ສຳເລັດ!`,
      editingShipping
        ? `Updated shipping carrier "${record.nameEn}"!`
        : `Added new shipping carrier "${record.nameEn}"!`
    );
  };

  const handleDeleteShippingMethod = (shipId: string) => {
    if (!requireAdminAuth('ລຶບບໍລິສັດຂົນສົ່ງ', 'delete shipping carriers')) return;
    const target = shippingMethods.find((s) => s.id === shipId);
    setShippingMethods((prev) => {
      const next = prev.filter((s) => s.id !== shipId);
      if (
        target &&
        selectedShippingProvider === target.nameEn &&
        next.length > 0
      ) {
        setSelectedShippingProvider(next[0].nameEn);
        if (next[0].defaultBranches.length > 0) {
          setShippingBranch(next[0].defaultBranches[0]);
        }
      }
      return next;
    });
    if (target) {
      showNotice(
        `ລຶບບໍລິສັດຂົນສົ່ງ "${target.nameEn}" ສຳເລັດ!`,
        `Deleted shipping carrier "${target.nameEn}"!`
      );
    }
  };

