  const resolveEmbeddedLogoDataUrl = async (
    preferredUrl?: string
  ): Promise<string> => {
    const candidate =
      preferredUrl || companyProfile.logoUrl || DEFAULT_COMPANY_LOGO_URL;
    if (candidate.startsWith('data:image/')) {
      return candidate;
    }
    const urlsToTry = Array.from(
      new Set([
        candidate,
        DEFAULT_COMPANY_LOGO_URL,
        new URL(DEFAULT_COMPANY_LOGO_URL, window.location.href).href,
      ])
    );
    for (const url of urlsToTry) {
      try {
        const res = await fetch(url, { credentials: 'include' });
        if (!res.ok) continue;
        const blob = await res.blob();
        if (!blob.type.startsWith('image/')) continue;
        const dataUrl = await new Promise<string>((resolve, reject) => {
          const reader = new FileReader();
          reader.onloadend = () =>
            typeof reader.result === 'string'
              ? resolve(reader.result)
              : reject(new Error('Empty reader result'));
          reader.onerror = () => reject(new Error('FileReader error'));
          reader.readAsDataURL(blob);
        });
        if (dataUrl.startsWith('data:image/')) {
          return dataUrl;
        }
      } catch {
        // Try next URL or fallback
      }
    }
    return GOLD_CRESCENT_PL_LOGO_SVG_DATA_URL;
  };

  // Automatically convert the default /assets/aistudio/02_478ebe23.jpg logo to a self-contained Base64 Data URL on mount
  useEffect(() => {
    let cancelled = false;
    if (!companyProfile.logoUrl.startsWith('data:image/')) {
      resolveEmbeddedLogoDataUrl(DEFAULT_COMPANY_LOGO_URL).then((dataUrl) => {
        if (!cancelled && dataUrl) {
          setCompanyProfile((prev) =>
            prev.logoUrl.startsWith('data:image/')
              ? prev
              : { ...prev, logoUrl: dataUrl }
          );
        }
      });
    }
    return () => {
      cancelled = true;
    };
  }, []);

  // Synchronously trigger browser print on both the dedicated print iframe and top-level #pl-universal-print-stage
  const executeImmediatePrintStage = (rawHtmlDoc?: string) => {
    const htmlSource = rawHtmlDoc || universalPrintDocHtml || '';
    if (htmlSource) {
      const stageEl = document.getElementById('pl-universal-print-stage');
      if (stageEl) {
        // Extract styles and body content while stripping any .toolbar elements so only the printable sheet prints
        const styleMatches = htmlSource.match(/<style[^>]*>[\s\S]*?<\/style>/gi) || [];
        const bodyMatch = htmlSource.match(/<body[^>]*>([\s\S]*?)<\/body>/i);
        const bodyInner = bodyMatch ? bodyMatch[1] : htmlSource;
        const cleanedBody = bodyInner.replace(
          /<div[^>]*class=["'][^"']*toolbar[^"']*["'][^>]*>[\s\S]*?<\/div>\s*/i,
          ''
        );
        stageEl.innerHTML = `${styleMatches.join('\n')}<div class="pl-print-stage-inner">${cleanedBody}</div>`;
      }
      document.body.classList.add('pl-universal-printing');
    }

    const iframe = document.getElementById(
      'pl-direct-print-iframe'
    ) as HTMLIFrameElement | null;
    let printedViaIframe = false;
    if (iframe && iframe.contentWindow) {
      try {
        iframe.contentWindow.focus();
        iframe.contentWindow.print();
        printedViaIframe = true;
      } catch {
        printedViaIframe = false;
      }
    }
    if (!printedViaIframe) {
      try {
        window.focus();
        window.print();
      } catch {
        // ignore if blocked
      }
    }
  };

  // Direct Browser Printer Dialog Helper (Pops up native Print / Save PDF directly AND opens interactive Print Studio Modal)
  const triggerDirectPrintHtmlDocument = (
    htmlDoc: string,
    noticeLo: string,
    noticeEn: string,
    openPreviewModal = true
  ) => {
    const titleMatch = htmlDoc.match(/<title[^>]*>([\s\S]*?)<\/title>/i);
    const extractedTitle = titleMatch
      ? titleMatch[1].trim()
      : 'PL Skincare Official Document';
    setUniversalPrintDocTitle(extractedTitle);
    setUniversalPrintDocHtml(htmlDoc);

    // 1. Synchronously populate top-level #pl-universal-print-stage for window.print()
    const stageEl = document.getElementById('pl-universal-print-stage');
    if (stageEl) {
      const styleMatches = htmlDoc.match(/<style[^>]*>[\s\S]*?<\/style>/gi) || [];
      const bodyMatch = htmlDoc.match(/<body[^>]*>([\s\S]*?)<\/body>/i);
      const bodyInner = bodyMatch ? bodyMatch[1] : htmlDoc;
      const cleanedBody = bodyInner.replace(
        /<div[^>]*class=["'][^"']*toolbar[^"']*["'][^>]*>[\s\S]*?<\/div>\s*/i,
        ''
      );
      stageEl.innerHTML = `${styleMatches.join('\n')}<div class="pl-print-stage-inner">${cleanedBody}</div>`;
    }
    document.body.classList.add('pl-universal-printing');

    // 2. Create a renderable (non-zero, non-hidden) offscreen iframe so Chromium renders all layout & images for printing
    const existing = document.getElementById('pl-direct-print-iframe');
    if (existing && existing.parentNode) {
      existing.parentNode.removeChild(existing);
    }
    const iframe = document.createElement('iframe');
    iframe.id = 'pl-direct-print-iframe';
    iframe.style.position = 'fixed';
    iframe.style.right = '0';
    iframe.style.bottom = '0';
    iframe.style.width = '794px';
    iframe.style.height = '1123px';
    iframe.style.border = '0';
    iframe.style.opacity = '0.01';
    iframe.style.pointerEvents = 'none';
    iframe.style.zIndex = '-10';
    document.body.appendChild(iframe);

    const doc = iframe.contentWindow?.document || iframe.contentDocument;
    if (doc) {
      doc.open();
      doc.write(htmlDoc);
      doc.close();
    }

    if (!openPreviewModal) {
      setUniversalPrintDocHtml(null);
    }

    showNotice(noticeLo, noticeEn);

    // 3. Trigger print immediately while user gesture activation is active, and also after images settle
    const runPrint = () => {
      executeImmediatePrintStage(htmlDoc);
    };

    const imgs = doc ? Array.from(doc.images || []) : [];
    const allComplete = imgs.every((img) => img.complete);
    if (imgs.length === 0 || allComplete) {
      runPrint();
    } else {
      let remaining = imgs.length;
      let printed = false;
      const checkDone = () => {
        remaining -= 1;
        if (remaining <= 0 && !printed) {
          printed = true;
          runPrint();
        }
      };
      imgs.forEach((img) => {
        if (img.complete) {
          checkDone();
        } else {
          img.onload = checkDone;
          img.onerror = checkDone;
        }
      });
      setTimeout(() => {
        if (!printed) {
          printed = true;
          runPrint();
        }
      }, 300);
    }
  };

