  // Deterministic 21x21 Simple QR Code helper for SVG and Canvas (never uses Bank QR)
  const computeSimpleQrModule = (
    seedText: string,
    r: number,
    c: number
  ): boolean => {
    const gridSize = 21;
    const isFinder = (topR: number, leftC: number): boolean | null => {
      const dr = r - topR;
      const dc = c - leftC;
      if (dr < 0 || dr > 6 || dc < 0 || dc > 6) return null;
      if (dr === 0 || dr === 6 || dc === 0 || dc === 6) return true;
      if (dr >= 2 && dr <= 4 && dc >= 2 && dc <= 4) return true;
      return false;
    };
    const f1 = isFinder(0, 0);
    if (f1 !== null) return f1;
    const f2 = isFinder(0, gridSize - 7);
    if (f2 !== null) return f2;
    const f3 = isFinder(gridSize - 7, 0);
    if (f3 !== null) return f3;
    if (
      (r === 7 && (c <= 7 || c >= gridSize - 8)) ||
      (c === 7 && (r <= 7 || r >= gridSize - 8)) ||
      (r === gridSize - 8 && c <= 7) ||
      (c === gridSize - 8 && r <= 7)
    ) {
      return false;
    }
    if (r === 6) return c % 2 === 0;
    if (c === 6) return r % 2 === 0;
    let h = 2166136261;
    const combined = `${seedText || 'PL-SKINCARE'}:${r}:${c}`;
    for (let i = 0; i < combined.length; i++) {
      h ^= combined.charCodeAt(i);
      h = Math.imul(h, 16777619);
    }
    return (h >>> 0) % 100 < 48;
  };

  const buildSimpleQrSvgMarkup = (
    qrItem: SimpleCardQrItem,
    pixelSize = 120
  ): string => {
    if (qrItem.customImageUrl) {
      return `<img src="${qrItem.customImageUrl}" alt="QR" style="width:${pixelSize}px;height:${pixelSize}px;object-fit:contain;border-radius:6px;background:#fff;" />`;
    }
    const cells: string[] = [];
    for (let r = 0; r < 21; r++) {
      for (let c = 0; c < 21; c++) {
        if (computeSimpleQrModule(qrItem.qrPayloadText, r, c)) {
          cells.push(
            `<rect x="${c}" y="${r}" width="1" height="1" fill="#18181B" />`
          );
        }
      }
    }
    return `<svg width="${pixelSize}" height="${pixelSize}" viewBox="0 0 21 21" shape-rendering="crispEdges" xmlns="http://www.w3.org/2000/svg" style="background:#FFFFFF;border-radius:6px;padding:4px;border:1px solid #E4D5B7;"><rect width="21" height="21" fill="#FFFFFF"/>${cells.join('')}</svg>`;
  };

