                                const c1 = row.zeroComm ? 0 : Math.round((row.lak * settings.level1Rate) / 100);
                                const c2 = row.zeroComm ? 0 : Math.round((row.lak * settings.level2Rate) / 100);
                                const c3 = row.zeroComm ? 0 : Math.round((row.lak * settings.level3Rate) / 100);
                                const c4 = row.zeroComm ? 0 : Math.round((row.lak * settings.level4Rate) / 100);
                                const totalComm = c1 + c2 + c3 + c4;
                                const netCompany = row.lak - totalComm;
